function ouvrirBoutique(id){
  const b = (marche().boutiques || []).filter(function(x){ return x.id === id; })[0];
  if(!b || boutiqueV) return;
  mReappro(b);
  const el = mk('div', 'mq');
  el.id = 'boutique';
  el.setAttribute('role', 'dialog'); el.setAttribute('aria-modal', 'true'); el.setAttribute('aria-label', trJeu(b.nom));
  el.style.setProperty('--mq', b.couleur || '#E8A33D');
  if(b.image){ el.style.backgroundImage = 'linear-gradient(rgba(5,7,11,.45),rgba(5,7,11,.45)),url("' + b.image + '")'; }
  ['click', 'pointerdown', 'touchstart'].forEach(function(t){ el.addEventListener(t, function(e){ e.stopPropagation(); }); });
  frameEl.appendChild(el);
  boutiqueV = { b: b, el: el, onglet: 'acheter', dit: mDire(b.repliques.accueil) };
  mDessine();
}
function fermerBoutique(){
  if(!boutiqueV) return;
  const v = boutiqueV;
  boutiqueV = null;
  if(v.el.parentNode) v.el.parentNode.removeChild(v.el);
  if(v.b.repliques.adieu){ try{ hudNotify(trJeu(v.b.repliques.adieu), 'info'); }catch(e){} }
  try{ hudSync(); }catch(e){}
  saveGame();
}
function mLigne(boite, image, titre, petit){
  const r = mk('div', 'mq-ligne');
  if(image){ const im = document.createElement('img'); im.src = image; im.alt = ''; r.appendChild(im); }
  const inf = mk('div', 'mq-info');
  inf.appendChild(mk('div', 'mq-titre', titre));
  if(petit) inf.appendChild(mk('div', 'mq-petit', petit));
  r.appendChild(inf);
  const a = mk('div', 'mq-actions');
  r.appendChild(a);
  boite.appendChild(r);
  return { ligne: r, actions: a };
}
function mBouton(boite, texte, fn, second, off){
  const b = mk('button', 'mq-b' + (second ? ' mq-b2' : ''), texte);
  b.type = 'button';
  if(off) b.disabled = true;
  b.addEventListener('click', fn);
  boite.appendChild(b);
  return b;
}
function mMontant(m, p){ return p + (m ? ' ' + (m.icone || m.nom) : ''); }
function mDessine(){
  const v = boutiqueV;
  if(!v) return;
  const b = v.b, el = v.el;
  const garde = el.querySelector('.mq-liste');
  const defile = garde ? garde.scrollTop : 0;
  el.textContent = '';
  const boite = mk('div', 'mq-boite');
  const tete = mk('div', 'mq-tete');
  tete.appendChild(mk('div', 'mq-nom', trJeu(b.nom)));
  (marche().monnaies || []).forEach(function(m){ tete.appendChild(mk('div', 'mq-solde', mMontant(m, mSolde(m)))); });
  boite.appendChild(tete);
  const x = mk('button', 'mq-x', '\u2715');
  x.type = 'button'; x.setAttribute('aria-label', 'Fermer');
  x.addEventListener('click', fermerBoutique);
  boite.appendChild(x);
  const ch = b.characterId ? dialogCharacterById(dialogGame(), b.characterId) : null;
  const pose = ch ? dialogPoseOf(ch, b.pose) : null;
  if(ch || v.dit){
    const pa = mk('div', 'mq-parole');
    if(pose && pose.image){ const im = document.createElement('img'); im.src = pose.image; im.alt = ch.name; pa.appendChild(im); }
    pa.appendChild(mk('div', 'mq-bulle', v.dit || ''));
    boite.appendChild(pa);
  }
  const onglets = [['acheter', 'Acheter']];
  if(b.rachat && b.rachat.actif) onglets.push(['vendre', 'Vendre']);
  if((b.trocs || []).length) onglets.push(['troc', 'Troc']);
  if(onglets.length > 1){
    const o = mk('div', 'mq-onglets');
    onglets.forEach(function(t){
      const bt = mk('button', t[0] === v.onglet ? 'on' : '', t[1]);
      bt.type = 'button';
      bt.addEventListener('click', function(){ v.onglet = t[0]; mDessine(); });
      o.appendChild(bt);
    });
    boite.appendChild(o);
  }
  const liste = mk('div', 'mq-liste');
  boite.appendChild(liste);
  const enListe = !b.vitrine || b.vitrine.mode === 'liste';
  if(v.onglet === 'vendre'){ if(enListe) mListeVendre(b, liste); else mVitrineVendre(b, liste); }
  else if(v.onglet === 'troc') mListeTroc(b, liste);
  else if(enListe) mListeAcheter(b, liste);
  else mVitrineAcheter(b, liste);
  mAllure(b, el, boite);
  el.appendChild(boite);
  liste.scrollTop = defile;
}
function mListeAcheter(b, liste){
  const lignes = (b.stock || []).filter(function(l){ return l.itemId && mObjet(l.itemId) && mCondsOk(l.conditions); });
  if(!lignes.length){ liste.appendChild(mk('div', 'mq-vide', 'Rien \xE0 vendre pour le moment.')); return; }
  const remise = mRemise(b);
  lignes.forEach(function(l){
    const it = mObjet(l.itemId), m = mMonnaie(l.monnaieId || b.monnaieId), p = mPrix(b, l), reste = mReste(b, l);
    const info = [];
    if(it.description) info.push(trJeu(it.description));
    if(reste !== Infinity) info.push(reste ? 'Reste ' + reste : '\xC9puis\xE9');
    if(remise > 0) info.push('Remise ' + remise + ' %');
    const r = mLigne(liste, it.image, trJeu(it.name), info.join(' \xB7 '));
    mBouton(r.actions, p ? mMontant(m, p) : 'Gratuit', function(){ mAcheter(b, l, r.ligne); }, false, !reste);
    if(b.marchandage && b.marchandage.actif && p > 0 && reste && vars[mCle('neg', b, l.itemId)] == null){
      mBouton(r.actions, 'Marchander', function(){ mMarchander(b, l, it); }, true);
    }
  });
}
function mListeVendre(b, liste){
  const stock = (b.stock || []).map(function(l){ return l.itemId; });
  const ids = Object.keys(inventory).filter(function(id){
    if(uiNumberOf(inventory[id]) <= 0 || !mObjet(id) || mRevente(b, id) == null) return false;
    return b.rachat.seulement !== 'stock' || stock.indexOf(id) >= 0;
  });
  if(!ids.length){ liste.appendChild(mk('div', 'mq-vide', 'Rien \xE0 vendre dans ton sac.')); return; }
  const m = mMonnaie(b.monnaieId);
  ids.forEach(function(id){
    const it = mObjet(id), p = mRevente(b, id), n = uiNumberOf(inventory[id]);
    const r = mLigne(liste, it.image, trJeu(it.name), n > 1 ? '\xD7 ' + n : '');
    mBouton(r.actions, 'Vendre ' + mMontant(m, p), function(){ mVendre(b, id, it, p, m); });
  });
}
function mListeTroc(b, liste){
  const noms = function(l){ return (l || []).filter(function(x){ return x.itemId; }).map(function(x){ const it = mObjet(x.itemId); return (x.qty > 1 ? x.qty + ' \xD7 ' : '') + (it ? trJeu(it.name) : x.itemId); }).join(', '); };
  (b.trocs || []).forEach(function(t){
    if(!mCondsOk(t.conditions)) return;
    const fait = parseFloat(vars[mCle('troc', b, t.id)]) || 0;
    const fini = t.fois > 0 && fait >= t.fois;
    const ok = (t.donne || []).every(function(x){ return !x.itemId || uiNumberOf(inventory[x.itemId]) >= x.qty; });
    const it0 = mObjet(((t.recoit || [])[0] || {}).itemId);
    const r = mLigne(liste, it0 ? it0.image : '', noms(t.recoit), 'Contre ' + noms(t.donne) + (fini ? ' \xB7 Termin\xE9' : ''));
    mBouton(r.actions, '\xC9changer', function(){ mTroquer(b, t); }, false, !ok || fini);
  });
  if(!liste.children.length) liste.appendChild(mk('div', 'mq-vide', 'Aucun \xE9change pour le moment.'));
}
function mRefus(ligne){
  try{ hudPlaySound('error'); }catch(e){}
  try{ vibre(30); }catch(e){}
  if(ligne){ ligne.classList.remove('mq-non'); void ligne.offsetWidth; ligne.classList.add('mq-non'); }
}
function mAcheter(b, l, ligne){
  const v = boutiqueV, it = mObjet(l.itemId), m = mMonnaie(l.monnaieId || b.monnaieId), p = mPrix(b, l), nom = trJeu(it.name);
  if(!mReste(b, l)){ v.dit = mDire(b.repliques.rupture, { objet: nom, prix: p }); mRefus(ligne); mDessine(); return; }
  if(m && mSolde(m) < p){
    v.dit = mDire(b.repliques.pauvre, { objet: nom, prix: p }) || 'Il te manque ' + (p - mSolde(m)) + '.';
    mDessine(); mRefus(v.el.querySelector('.mq-bulle'));
    return;
  }
  const k = mCle('vendu', b, l.itemId);
  vars[k] = (parseFloat(vars[k]) || 0) + 1;
  mDepense(m, p);
  mNote(nom + (p ? ' \xB7 ' + mMontant(m, p) : ''));
  const acts = [{ type: 'give_item', itemId: l.itemId, amount: 1 }];
  if(m && p) acts.unshift({ type: 'ajouter', key: m.key, amount: -p });
  runActions(acts.concat(b.surAchat || []));
  try{ hudPlaySound('notify'); }catch(e){}
  marchePaliers();
  v.dit = mDire(b.repliques.achat, { objet: nom, prix: p });
  mDessine();
}
function mVendre(b, id, it, p, m){
  const v = boutiqueV, nom = trJeu(it.name), acts = [{ type: 'remove_item', itemId: id, amount: 1 }];
  if(m) acts.push({ type: 'ajouter', key: m.key, amount: p });
  runActions(acts.concat(b.surVente || []));
  try{ hudPlaySound('notify'); }catch(e){}
  v.dit = mDire(b.repliques.vente, { objet: nom, prix: p });
  mDessine();
}
function mMarchander(b, l, it){
  const v = boutiqueV, ma = b.marchandage, nom = trJeu(it.name);
  let chance = ma.chance || 0;
  if(ma.variable) chance += (parseFloat(vars[ma.variable]) || 0) * (ma.bonus || 0);
  const ok = Math.random() * 100 < chance;
  vars[mCle('neg', b, l.itemId)] = ok ? (ma.reduction || 0) : -(ma.surcout || 0);
  const p = mPrix(b, l);
  v.dit = mDire(ok ? b.repliques.negoOk : b.repliques.negoKo, { objet: nom, prix: p }) || (ok ? 'Bon, d' + String.fromCharCode(39) + 'accord.' : 'Non.');
  saveGame();
  mDessine();
}
function mTroquer(b, t){
  const v = boutiqueV, k = mCle('troc', b, t.id);
  vars[k] = (parseFloat(vars[k]) || 0) + 1;
  const acts = [];
  (t.donne || []).forEach(function(x){ if(x.itemId) acts.push({ type: 'remove_item', itemId: x.itemId, amount: x.qty }); });
  (t.recoit || []).forEach(function(x){ if(x.itemId) acts.push({ type: 'give_item', itemId: x.itemId, amount: x.qty }); });
  runActions(acts);
  try{ hudPlaySound('notify'); }catch(e){}
  v.dit = mDire(b.repliques.troc);
  mDessine();
}
function marcheJournal(box){
  const l = vars.__achats || [];
  if(!l.length) return;
  box.appendChild(mk('div', 'jr-head', 'Achats \xB7 ' + l.length));
  const d = mk('div', 'pnl-list');
  l.slice().reverse().forEach(function(t){ d.appendChild(mk('div', 'pnl-row', t)); });
  box.appendChild(d);
}
if(BOUTIQUE_TEST) setTimeout(function(){ ouvrirBoutique(BOUTIQUE_TEST); }, 700);


