    const el = document.createElement('div');
    el.className = 'sc-rep sc-' + (r.style || 'discret');
    el.style.width = r.taille + 'px'; el.style.height = r.taille + 'px';
    el.setAttribute('data-sc-rep', r.id);
    if(r.style === 'image' && r.image){ el.style.backgroundImage = 'url(' + r.image + ')'; }
    else if(r.style !== 'invisible' && r.label){ el.textContent = r.label; }
    mount.appendChild(el);
