    type: "line", dialogId: d.id, nodeId: n.id, style: style, cast: cast, nom: nomVu,
    speaker: speaker, pose: dialogPoseOf(speaker, n.pose),
    text: parsed, letters: timed.letters, duration: timed.duration,
    fx: n.fx || "none", voiceClip: n.voiceClip || "",
    history: state.history || [],
