// declare en var : setScreen() peut appeler needsRedraw() avant cette ligne
var idleFrames = 0, derniereVue = '', dernierLeger = 0;
function videoActive(){ try{ return !!(videoEl && !videoEl.paused); }catch(e){ return false; } }
function enMouvement(){ try{ return !!dragging; }catch(e){ return false; } }
function lampeBouge(){ try{ return !!(lampeEl && lampeEl.style.display === 'block' && (Math.abs(lampeX - lampeCX) > 0.002 || Math.abs(lampeY - lampeCY) > 0.002)); }catch(e){ return false; } }
function needsRedraw(){ idleFrames = 0; }
function loop(){
  if(animsCamera.length){ const t = performance.now(); animsCamera = animsCamera.filter(function(f){ return !f(t); }); }
  try{ imTick(); }catch(e){}
  camera.rotation.set(pitch + imOff.p,yaw + imOff.y,0,'YXZ');
  // la scene 360 ne bouge pas pendant un dialogue : on arrete de la redessiner
  const vueSig = yaw.toFixed(4) + ',' + pitch.toFixed(4) + ',' + camera.fov.toFixed(2) + ',' + mount.clientWidth + 'x' + mount.clientHeight + ',' + (mat.map ? mat.map.uuid : '');
  if(vueSig !== derniereVue){ derniereVue = vueSig; idleFrames = 0; }
  const anime = animsCamera.length || sceneTicks.length || sceneMarques.length || bulles.length || videoActive() || enMouvement() || BANDE_ANNONCE || lampeBouge() || imAnime();
  const frozen = (playerScreen === 'dialogue' && idleFrames > 4) || (!anime && idleFrames > 20);
  if(frozen){
    const t9 = performance.now();
    if(t9 - dernierLeger > 200){ dernierLeger = t9; try{ lot5Tick(yaw, pitch); }catch(e){} try{ lot678Tick(yaw, pitch); }catch(e){} }
  }
  if(!frozen){
    imRendu();
    project();
    if(sceneTicks.length) sceneTicks.slice().forEach(function(f){ try{ f(yaw, pitch); }catch(e){} });
    idleFrames++;
  }
  requestAnimationFrame(loop);
}
(function(){
  saveEnabled = false;
  if(!GAME.scenes.length){ showModal("Ce jeu n'a aucune sc\xE8ne."); return; }
  if(TEST_START){
    // test depuis une sc\xE8ne : on saute l'accueil et on part de l'\xE9tat demand\xE9
    const sid = GAME.scenes.some(function(s){ return s.id === TEST_START.sceneId; }) ? TEST_START.sceneId : startSceneId();
    inventory = Object.assign({}, TEST_START.inventory || {});
    vars = Object.assign(initialVars(GAME.variables), TEST_START.vars || {});
    // un essai peut partir d'une carte deja parcourue (apercu du studio, mode test)
    discovered = new Set([sid].concat((TEST_START.discovered || []).filter(function(id){
      return GAME.scenes.some(function(s){ return s.id === id; });
    })));
    saveEnabled = true;
    loadScene(sid);
    markSaved();
    applyUserSettings();
    setScreen('playing');
    installBack();
    // un essai depuis le studio peut s'ouvrir directement sur un panneau
    if(TEST_START.screen === 'inventory') openInv();
    else if(TEST_START.screen === 'map') openMap();
    else if(TEST_START.screen === 'pause') openPause();
    if(TEST_START.dialogue && TEST_START.dialogue.dialogId){
      openDialogue(TEST_START.dialogue.dialogId, TEST_START.dialogue.nodeId || '');
    }
    return;
  }
  loadScene(startSceneId());   // d\xE9cor derri\xE8re l'accueil ; rien n'est sauvegard\xE9 tant que la partie n'a pas commenc\xE9
  applyUserSettings();
  showHome(false);
  installBack();
})();
loop();
